#!/usr/bin/env bash
set -euo pipefail
GSZ=/opt/gsz
TS=$(date +%Y%m%d-%H%M%S)
BK="$GSZ/.bak-step160-$TS"
echo "==> step160: portal/bot products show real synced stock count (#5)"
echo "    backup: $BK"
mkdir -p "$BK/routes"
cp "$GSZ/routes/products.js" "$BK/routes/" 2>/dev/null || true
cp "$GSZ/routes/checkout.js" "$BK/routes/" 2>/dev/null || true

restore(){ echo "!! error — restoring"; cp "$BK/routes/products.js" "$GSZ/routes/" 2>/dev/null || true; cp "$BK/routes/checkout.js" "$GSZ/routes/" 2>/dev/null || true; }
trap 'restore' ERR

PATCHER=$(mktemp /tmp/patch_step160.XXXXXX.js)
echo "" | base64 -d > "$PATCHER"
echo "==> applying"
NODE_PATH="$GSZ/node_modules" node "$PATCHER" "$GSZ"
echo "==> validating"
node --check "$GSZ/routes/products.js"
node --check "$GSZ/routes/checkout.js"
echo "    node --check ok (2 files)"

echo "==> restarting"
pm2 restart gsz >/dev/null 2>&1 || pm2 restart gsz
CODE=000
for i in $(seq 1 25); do sleep 1; CODE=$(curl -s -o /dev/null -w '%{http_code}' http://127.0.0.1:3900/ || echo 000); [ "$CODE" = "200" ] && break; done
[ "$CODE" = "200" ] || { echo "    homepage $CODE after ${i}s"; false; }
echo "    homepage 200: OK (after ${i}s)"

rm -f "$PATCHER"
trap - ERR
echo ""
echo "==> step160 OK  Portal / amember / stock products now show the bot's real available count (e.g. '23 in stock') on the product page and checkout, from the synced stock field — not a flat 'In stock'. Unlimited (amember) still reads 'In stock' as intended. If a portal product still shows no number, run a Bot Sync (admin → mapping → Sync) so stock is fresh."
